', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-react--style-modern--validation-message-present/google/gemini-3-flash-preview__s2/app.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='const { useState, useRef } = React;

const ContactForm = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: ''
  });

  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const fullNameRef = useRef(null);
  const emailRef = useRef(null);
  const phoneRef = useRef(null);

  const validate = () => {
    const newErrors = {};

    if (!formData.fullName.trim()) {
      newErrors.fullName = 'Full name is required';
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email address is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    if (formData.phone && !/^\+?[\d\s\-\(\)]{7,20}$/.test(formData.phone)) {
       newErrors.phone = 'Please enter a valid phone number format';
    }

    return newErrors;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const validationErrors = validate();
    if (Object.keys(validationErrors).length === 0) {
      setSubmitted(true);
      setErrors({});
    } else {
      setErrors(validationErrors);
      setSubmitted(false);

      // Focus first invalid field
      if (validationErrors.fullName) {
        fullNameRef.current.focus();
      } else if (validationErrors.email) {
        emailRef.current.focus();
      } else if (validationErrors.phone) {
        phoneRef.current.focus();
      }
    }
  };

  if (submitted) {
    return (
      <div className="container" role="status" aria-live="polite">
        <h1>Thank you!</h1>
        <p className="subtitle">We've received your support request and will get back to you shortly.</p>
        <button type="button" onClick={() => { setSubmitted(false); setFormData({fullName: '', email: '', phone: ''}); }}>
          Send another message
        </button>
      </div>
    );
  }

  return (
    <div className="container">
      <header>
        <h1>Contact Support</h1>
        <p className="subtitle">Fill out the form below and we'll be in touch.</p>
      </header>

      <p className="required-note">Fields marked with an asterisk (*) are required.</p>

      <form onSubmit={handleSubmit} noValidate>
        <div className="form-field">
          <label htmlFor="fullName">Full Name <span aria-hidden="true">*</span></label>
          <input
            type="text"
            id="fullName"
            name="fullName"
            ref={fullNameRef}
            value={formData.fullName}
            onChange={handleChange}
            placeholder="John Doe"
            autoComplete="name"
            className={errors.fullName ? 'error' : ''}
            aria-invalid={!!errors.fullName}
            aria-describedby={errors.fullName ? 'fullName-error' : undefined}
            required
            aria-required="true"
          />
          <div id="fullName-error" className="error-message" role="alert">
            {errors.fullName && `Error: ${errors.fullName}`}
          </div>
        </div>

        <div className="form-field">
          <label htmlFor="email">Email Address <span aria-hidden="true">*</span></label>
          <input
            type="email"
            id="email"
            name="email"
            ref={emailRef}
            value={formData.email}
            onChange={handleChange}
            placeholder="john@example.com"
            autoComplete="email"
            className={errors.email ? 'error' : ''}
            aria-invalid={!!errors.email}
            aria-describedby={errors.email ? 'email-error' : undefined}
            required
            aria-required="true"
          />
          <div id="email-error" className="error-message" role="alert">
            {errors.email && `Error: ${errors.email}`}
          </div>
        </div>

        <div className="form-field">
          <label htmlFor="phone">Phone Number (Optional)</label>
          <input
            type="tel"
            id="phone"
            name="phone"
            ref={phoneRef}
            value={formData.phone}
            onChange={handleChange}
            placeholder="(123) 456-7890"
            autoComplete="tel"
            className={errors.phone ? 'error' : ''}
            aria-invalid={!!errors.phone}
            aria-describedby={`phone-helper ${errors.phone ? 'phone-error' : ''}`.trim()}
          />
          <div id="phone-helper" className="helper-text">
            Expected format: (123) 456-7890 or 123-456-7890
          </div>
          <div id="phone-error" className="error-message" role="alert">
            {errors.phone && `Error: ${errors.phone}`}
          </div>
        </div>

        <button type="submit">Submit Request</button>
      </form>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ContactForm />);
